import React, { useState } from 'react';
import styles from './RegistrationForm.module.css'; // Menggunakan ulang style container

const LoginForm = () => {
  const [loginData, setLoginData] = useState({ email: '', password: '' });
  const [error, setError] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setLoginData(prev => ({ ...prev, [name]: value }));
  };

  const handleLogin = (e) => {
    e.preventDefault();
    if (!loginData.email || !loginData.password) {
      setError('Email dan Password wajib diisi');
    } else {
      setError('');
      alert(`Berhasil login dengan email: ${loginData.email}`);
    }
  };

  return (
    <div className={styles.container}>
      <h1 className={styles.title}>Login Form</h1>
      {error && <p style={{ color: 'red', textAlign: 'center' }}>{error}</p>}
      <form className={styles.form} onSubmit={handleLogin}>
        <div className={styles.formGroup}>
          <label>Email Address</label>
          <input type="email" name="email" className={styles.input} onChange={handleChange} />
        </div>
        <div className={styles.formGroup}>
          <label>Password</label>
          <input type="password" name="password" className={styles.input} onChange={handleChange} />
        </div>
        <button type="submit" className={styles.submitButton}>Login</button>
      </form>
    </div>
  );
};

export default LoginForm;
